function react(id,emoji){return mutate({action:'react',id,emoji})}
function openAsk(){modal(`<h2>🙋 Ask ${displayName('Dad')} & ${displayName('Mom')}</h2><div class=field><label for=rt>Type</label><select id=rt><option>Permission</option><option>Purchase</option><option>Ride</option><option>Schedule Change</option><option>Question</option></select></div><div class=field><label for=rq>What would you like to ask?</label><textarea id=rq rows=4 maxlength=4000></textarea></div><button class="btn primary" onclick=addRequest()>Send request 💬</button>`)}
